{
  "claims": [
    {
      "anchor": "If you increment a counter 100 times, the AOF ends up with 100 entries",
      "claim_text": "Incrementing a counter 100 times results in 100 entries in the AOF.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S1 states exactly this example."
    },
    {
      "anchor": "only the final value matters",
      "claim_text": "Only the final counter value matters for the dataset.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S1", "rel": "entails", "sub": "containing the final value"}
      ],
      "check": null,
      "reasoning": "P0.S1 says the key contains the final value."
    },
    {
      "anchor": "99 of them are not needed to rebuild the current state",
      "claim_text": "99 of the 100 AOF entries are not needed to rebuild the current state.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S2 states this directly."
    },
    {
      "anchor": "BGREWRITEAOF writes the shortest sequence of commands needed to rebuild the current dataset in memory",
      "claim_text": "BGREWRITEAOF writes the shortest sequence of commands needed to rebuild the current dataset in memory.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P1.S1 states this directly."
    },
    {
      "anchor": "like RDB saving, the rewrite is done by a forked child process",
      "claim_text": "The AOF rewrite is done by a forked child process, like RDB saving.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "Passages mention background rewrite but not forked child process."
    },
    {
      "anchor": "Automatic log rewriting has been supported since Redis 2.2",
      "claim_text": "Automatic log rewriting has been supported since Redis 2.2.",
      "kind": "version",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "refutes"},
        {"sid": "P1.S3", "rel": "refutes"}
      ],
      "check": {"kind": "version", "left": "2.2", "op": ">=", "right": "2.4"},
      "reasoning": "P1.S3 says automatic rewriting since 2.4, contradicting 2.2."
    },
    {
      "anchor": "The Redis documentation recommends running AOF alone for most deployments",
      "claim_text": "The Redis documentation recommends running AOF alone for most deployments.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P2.S0 says AOF alone is discouraged."
    }
  ]
}
